async function login(email, password) {
  const user = await db.User.findOne({ where: { email }, attributes: [..'password'..] })
  if (user === null) throw new NotFoundError(`User "${email}" not found`)
  const passwordMatches = await user.comparePassword(password)
  if (passwordMatches !== true) throw new PasswordNotMatchingError()
  const userPlain = user.get({ plain: true }); delete userPlain.password
  return userPlain
}

async function forgotPassword(email, useragent) {
  const user = await db.User.findOne({ where: { email } })
  if (user === null) throw new NotFoundError('User not found')
  const scope = ['reset-password:write']
  const session = await this.session.create(user.id, scope, 60*60, useragent)
  return { session, user: user.get({ plain: true }) }
}

