async function revoke(userId, sessionId) {
  const session = await db.Session.findOne({ attributes:['id'], where: { id: sessionId, user_id: userId } })
  if (session === null) throw new NotFoundError('Session not found')
  await session.update({ revoked: true })
  this.cache.set(`revoked_session:${sessionId}`, true)
  return { id: session.id, revoked: true }
}

